// Data types for the catalog. Instances are generated by tool/catalog_gen
// into `generated/catalog_data.g.dart`.

/// One constructor or method parameter.
class CatalogParam {
  /// Creates a parameter.
  const CatalogParam({
    required this.name,
    required this.type,
    required this.isNamed,
    required this.isRequired,
    required this.defaultValue,
    required this.doc,
  });

  /// Name.
  final String name;

  /// Declared type.
  final String type;

  /// Named vs positional.
  final bool isNamed;

  /// Required.
  final bool isRequired;

  /// Default value source, if any.
  final String? defaultValue;

  /// Doc comment.
  final String doc;
}

/// A constructor, method, getter or property.
class CatalogMember {
  /// Creates a member.
  const CatalogMember({
    required this.kind,
    required this.name,
    required this.signature,
    required this.doc,
    required this.params,
  });

  /// `constructor`, `factory`, `property`, `getter`, `method`, ...
  final String kind;

  /// Display name.
  final String name;

  /// One-line signature.
  final String signature;

  /// Doc comment.
  final String doc;

  /// Parameters.
  final List<CatalogParam> params;

  /// Whether this is a constructor or factory.
  bool get isConstructor => kind == 'constructor' || kind == 'factory';
}

/// A documented class.
class CatalogClass {
  /// Creates a class.
  const CatalogClass({
    required this.name,
    required this.superclass,
    required this.doc,
    required this.members,
  });

  /// Name.
  final String name;

  /// Superclass, if any.
  final String? superclass;

  /// Doc comment.
  final String doc;

  /// Constructors, then properties, getters and methods.
  final List<CatalogMember> members;
}

/// An enum used by the page's classes.
class CatalogEnum {
  /// Creates an enum.
  const CatalogEnum({
    required this.name,
    required this.doc,
    required this.values,
  });

  /// Name.
  final String name;

  /// Doc comment.
  final String doc;

  /// `(value, doc)` pairs.
  final List<(String, String)> values;
}

/// A preview scenario's declared size.
class CatalogPreview {
  /// Creates the info.
  const CatalogPreview({
    required this.name,
    required this.function,
    required this.width,
    required this.height,
  });

  /// Scenario name (registry `name`).
  final String name;

  /// Builder function name.
  final String function;

  /// Declared width, if any.
  final double? width;

  /// Declared height, if any.
  final double? height;
}

/// One catalog page.
class CatalogEntry {
  /// Creates an entry.
  const CatalogEntry({
    required this.id,
    required this.name,
    required this.category,
    required this.phase,
    required this.planNumber,
    required this.slug,
    required this.summary,
    required this.classes,
    required this.enums,
    required this.previews,
  });

  /// URL-safe id.
  final String id;

  /// Display name; the preview registry group.
  final String name;

  /// Navigation category.
  final String category;

  /// Roadmap phase.
  final int phase;

  /// Rebuild plan inventory number, if any.
  final int? planNumber;

  /// Cloudscape guideline page slug, if upstream documents it.
  final String? slug;

  /// One-line description.
  final String summary;

  /// API classes.
  final List<CatalogClass> classes;

  /// Enums referenced by [classes].
  final List<CatalogEnum> enums;

  /// Preview sizes, in source order.
  final List<CatalogPreview> previews;

  /// The Cloudscape guideline page, if any.
  Uri? get guidelineUrl => slug == null
      ? null
      : Uri.parse('https://cloudscape.design/components/$slug/');
}
